CREATE TRIGGER `documents_service_completed_date_insert` BEFORE INSERT ON `documents` WHEN NEW.service_completed_on IS NOT NULL AND (date(NEW.service_completed_on) IS NOT NEW.service_completed_on OR NEW.type NOT IN ('tax_invoice', 'export_invoice')) BEGIN SELECT RAISE(ABORT, 'documents_service_completed_date_insert: a service date is a real date, and only a tax or export invoice has one'); END;
